props.onChange:
(
  /* Make sure they scanned something */
  ($$.newValue) ? 
    /* VCF mean inventory */
    ($substring($$.newValue, 0, 3) = "VCF") ? 
      (
        $obj := $executeFlow("shipperLineFulfillmentFromPickScreen", {
          "action": "Pick",
          "shipperFulfillmentId": "cleykxewp00bt019wd16e9fy0",
          "inventoryNumber": $$.newValue
        });

        /* Reload the tables */
        $components.Table5.fn.search();
        $components.Table6.fn.search();

        /* Share the message with user */
        $addNotificationMessage($obj.message, $obj.options);

        /* Clear out the scan value, set the source location */
        {
          "scanValue": null
        }
      )
)

transforms.post:
(

  $step := $components.JsonData.data;
  $scannedValue := result.pickup;

  $step.type = "master"?
  (
    $step.masterUnit.number != $scannedValue ? 
      $throw("The scanned value doesn't match the suggested master (" & $step.masterUnit.number & ")")
          : 
      "" ;
  )
    :
  (
    $data := $query({
      "statement":'
        query ($number: String!){
          inventory(where:{
            number:{_eq: $number}
          }){
            edges{
              node{
                id
                number
                masterUnit{
                  id
                  number
                }
              }
            }
          }
        }
      ',
      "variables":{ "number": $scannedValue}}
    ).inventory.edges.node;

    $isNilOrEmpty($data.masterUnit.number) or $data.masterUnit.number != $step.masterUnit.number? 
      $throw("The scanned value is not on the suggested master (" & $step.masterUnit.number & ")")
          : 
      $data ; 
  )
)

transforms.pre:
(
  $step := $components.JsonData.data;

  $data := $query({
    "statement":'
       query ($inventoryId: String) {
        shipperLineFulfillmentStep(where:{
          inventoryId:{_eq: $inventoryId}
        }) {
          total
        }
      }
     ',
    "variables":{"inventoryId": data.id}
  });

  $data.shipperLineFulfillmentStep.total = 0?
    {
      "payload": {
        "where":{ "id": $step.id },
        "update":{
          "isPicked": true,
          "userId": $metadata.user.id,
          "inventoryId":  $step.type="container"? data.id
        }
      }
    }
  :
    $throw("The container (" & data.number & ") is scanned is already been picked");

)

action.transformation:
(
  $step := $components.JsonData.data;
  $newSerial := newSerial;


  $inventory := $aggregate(
    "inventory",
    [
      {
        "$match":{
          "number":{ "$eq": $newSerial }
        }
      },
      {
        "$lookup":{
          "from": "shipperLineFulfillmentStep",
          "localField": "id",
          "foreignField": "inventoryId",
          "as": "steps",
          "pipeline":[
            {
              "$lookup":{
                "from": "shipperLineFulfillment",
                "localField": "shipperLineFulfillmentId",
                "foreignField": "id",
                "as": "shipperLineFulfillment",
                "pipeline":[
                  {
                    "$lookup":{
                      "from": "shipperLine",
                      "localField": "shipperLineId",
                      "foreignField": "id",
                      "as": "shipperLine",
                      "pipeline":[
                        {
                          "$lookup":{
                            "from": "shipper",
                            "localField": "shipperId",
                            "foreignField": "id",
                            "as": "shipper"
                          }
                        }
                      ]
                    }
                  }
                ]
              }
            }
          ]
        }
      },
      {
        "$lookup":{
          "from": "item",
          "localField": "itemId",
          "foreignField": "id",
          "as": "item"
        }
      },
      {
        "$project":{
          "number": 1,
          "itemId": 1,
          "item": 1,
          "inventoryType": 1,
          "steps": 1,
          "quantity": 1,
          "location": 1
        }
      }
    ]
  );

  $master := $aggregate(
    "masterUnit",
    [
      {
        "$match":{
          "number":{ "$eq": $newSerial }
        }
      },
      {
        "$lookup":{
          "from": "shipperLineFulfillmentStep",
          "localField": "id",
          "foreignField": "masterUnitId",
          "as": "steps",
          "pipeline":[
            {
              "$lookup":{
                "from": "shipperLineFulfillment",
                "localField": "shipperLineFulfillmentId",
                "foreignField": "id",
                "as": "shipperLineFulfillment",
                "pipeline":[
                  {
                    "$lookup":{
                      "from": "shipperLine",
                      "localField": "shipperLineId",
                      "foreignField": "id",
                      "as": "shipperLine",
                      "pipeline":[
                        {
                          "$lookup":{
                            "from": "shipper",
                            "localField": "shipperId",
                            "foreignField": "id",
                            "as": "shipper"
                          }
                        }
                      ]
                    }
                  }
                ]
              }
            }
          ]
        }
      },
      {
        "$lookup":{
          "from": "inventory",
          "localField": "id",
          "foreignField": "masterUnitId",
          "as": "inventory",
          "pipeline":[
              {
                "$lookup":{
                  "from": "item",
                  "localField": "itemId",
                  "foreignField": "id",
                  "as": "item"
                }
              }
          ]
        }
      },
      {
        "$project":{
          "number": 1,
          "inventory": 1,
          "steps": 1
        }
      }
    ]
  );

  /* Create the gql payload */
  $createStep := function($v){{

      "payload": [$v.{
        "where":{ "id": $step.shipperLineFulfillment.id & "::" & $v.number },
        "create":{
            "containerType": containerType,
            "quantity": quantity,
            "isCompleted": false,
            "isPicked": false,
            "isSkipped": false,
            "inventoryId": inventoryId,
            "masterUnitId": masterUnitId,
            "type": type,
            "location": location,
            "shipperLineFulfillmentId": $step.shipperLineFulfillment.id 
        },
        "update":{
            "containerType": containerType,
            "quantity": quantity,
            "isCompleted": false,
            "isPicked": false,
            "isSkipped": false,
            "inventoryId": inventoryId,
            "masterUnitId": masterUnitId,
            "type": type,
            "location": location,
            "shipperLineFulfillmentId": $step.shipperLineFulfillment.id 
        }
      }]
    }
  };

  /* Check if there is a container  */
  $res := $count($inventory) > 0?
    (
      $container := $first($inventory);

      $container.inventoryType != $step.containerType?
        {
          "error": true,
          "message": $newSerial &  "has the incorrect container type (" & $container.inventoryType & ")"
        }
      :
      $container.itemId != $step.shipperLineFulfillment.item.id ? 
        {
          "error": true,
          "message":  $newSerial & " has the incorrect part no ( " & $container.item.itemNumber & " )"
        }
      :
      $count($container.steps) != 0?
        {
          "error": true,
          "message": $newSerial & " is already alloted to shipper " & $container.steps.shipperLineFulfillment.shipperLine.shipper.name
        }
      :
        $createStep($merge([
            $container,
            {
              "containerType": $container.inventoryType,
              "type": "container",
              "inventoryId": $container._id
            }
          ]))
      ;
    )
  :
  /* Check if there is a master */
  $count($master) > 0?
    (
      $container := $first($master.inventory);

      $container.inventoryType != $step.containerType?
        {
          "error": true,
          "message": $newSerial & " has the incorrect container type (" & $container.inventoryType & ")"
        }
      :
      $container.itemId != $step.shipperLineFulfillment.item.id ? 
        {
          "error": true,
          "message":  $newSerial & " has the incorrect part no ( " & $container.item.itemNumber & " )"
        }
      :
      $count($master.steps) != 0?
        {
          "error": true,
          "message": $newSerial & " is already alloted to shipper " & $master.steps.shipperLineFulfillment.shipperLine.shipper.name
        }
      :
        $createStep(
          $merge([
            $container,
            {
              "containerType": $container.inventoryType,
              "type": "master"
            }
          ])
        )
      ;
    )
  :
    /* If nothing was found */
    { 
      "error": true,
      "message": "Could not find inventory for " & $newSerial
    };

  $res.error ? 
    $showConfirmDialog(
      $res.message,
        { 
          'title': 'Warning',
          'delayTimeinSeconds' : 10,
          'icon' : 'check',
          'buttonColor': 'green'
        }
    )
  :
    $addNotificationMessage("Alloted " & $newSerial, {
      "message": "Alloted " & $newSerial,
      "severity": "success"
    });

 $res
)

